import re
P=".rcs/drafts/v001/paper.md"
t=open(P,encoding="utf-8").read()
def rep(a,b):
    global t
    assert a in t,a[:60]
    t=t.replace(a,b,1)
rep("Table 1 defines what is measured for RQ1; it reports no submissions. Its takeaways are that the suite covers audio and image inputs, with Top-1 accuracy for three tasks and the threshold-free AUC for anomaly detection, and that all reference models are small enough for typical microcontrollers {C001, C002}.","Table 1 defines what is measured for RQ1; it reports no submissions. The suite covers audio and image inputs, with Top-1 accuracy for three tasks and the threshold-free AUC for anomaly detection, and all reference models are small enough for typical microcontrollers {C001, C002}.")
rep("Keyword spotting recognises specific spoken words or short phrases; wake-word detection and command phrases both need continuous operation, low latency and low power {C003}. ","Keyword spotting recognises specific spoken words or short phrases, which needs low latency and low power {C003}. ")
rep(", split so that each speaker appears in only one of the training, validation and test subsets {C003}",", split so that each speaker appears in only one subset {C003}")
rep("They chose it because it fits the memory of most microcontrollers and uses standard layers {C003}. ","It fits the memory of most microcontrollers and uses standard layers {C003}. ")
rep("The task uses CIFAR-10","The benchmark uses CIFAR-10")
rep("The authors say only that targets accommodate quantization and rounding differences; the paper does not explain why the visual wake words margin is larger, nor state whether its \"about 86%\" is for the full-precision or quantized model {C005}.","The paper does not explain why the visual wake words margin is larger, nor state whether its \"about 86%\" is for the full-precision or quantized model {C005}.")
rep("Post-training quantization converts a trained model to lower precision without further training; quantization-aware training, used by one submission described later, includes the lower precision during training. ","Post-training quantization converts a trained model to lower precision without further training; quantization-aware training includes the lower precision during training. ")
rep("The paper does not report how much the five runs varied, so the spread behind a median score is unknown {C006}. And because only model inference is measured, the reported cost is not that of a full application {C006, L003}.","The paper does not report how much the five runs varied {C006}, and because only model inference is measured, the reported cost is not that of a full application {C006, L003}.")
rep("Level-shifter power is excluded, only power delivered to the core is measured, and only one supply may power the core, so batteries, supercapacitors or energy harvesters cannot be used to circumvent the measurement {C008}.","Level-shifter power is excluded, only power delivered to the core is measured, and only one supply may power the core, so batteries or energy harvesters cannot circumvent the measurement {C008}.")
rep("the text says the benchmarks cover a wide scope in latency and energy and that each reference meets its minimum accuracy {C013}. The numerical values appear only in the figure, which is not available in our text, so we cannot report them, nor any submission's numerical results, which the paper leaves to an external results site {C013, L001}.","the text says the benchmarks cover a wide scope in latency and energy and that each reference meets its minimum accuracy {C013}. The values appear only in the figure, which is not in our text, so we cannot report them, nor any submission's numerical results {C013, L001}.")
rep("Fixing feature extraction rigidly, the authors add, would preclude joint optimization of features and model that can be critical on constrained systems, and including it has its own costs: for one second of audio, a non-streaming benchmark would run one inference but 40 feature extraction cycles, over-emphasizing feature extraction {C016}. They aim to include pre-processing in future versions {C018, L003}. Related to this, the time-domain tasks are naturally streaming, but limited bandwidth between runner and device makes it hard to reproduce streaming without adding transfer delays {L003}.","Fixing feature extraction rigidly would preclude joint optimization of features and model, while including it would, for one second of audio, mean one inference but 40 feature extraction cycles, over-emphasizing its cost {C016}. The authors aim to include pre-processing in future versions {C018, L003}. Separately, the time-domain tasks are naturally streaming, but limited runner-to-device bandwidth makes streaming hard to reproduce without transfer delays {L003}.")
rep("The authors want the suite to evolve, with tasks in domains such as wearables, medical devices and environmental monitoring, and also to be a long-term record, which requires stability; they envision keeping a subset of tasks stable for a multi-year perspective {C018, L006}.","The authors want the suite to evolve, with tasks in domains such as wearables, medical devices and environmental monitoring, and also to be a long-term record, so they envision keeping a subset of tasks stable {C018, L006}.")
rep("The paper offers a specification with fixed tasks and targets, an inference-only procedure with median-of-five scoring, and closed and open divisions {C001, C006, C007}. Its support","The paper offers fixed tasks and targets, an inference-only procedure with median-of-five scoring, and closed and open divisions {C001, C006, C007}. Its support")
rep("Latency and energy values were not available to us in text form, so we describe them only qualitatively {L001}.","Latency and energy values were not available to us in text form and are described only qualitatively {L001}.")
open(P,"w",encoding="utf-8").write(t)
main=t.split("## References")[0]
print(len(re.sub(r"\{[CL]\d{3}(, [CL]\d{3})*\}","",main).split()))
tt=re.sub(r"^\|.*\n","",main,flags=re.M)
print("without tables",len(re.sub(r"\{[CL]\d{3}(, [CL]\d{3})*\}","",tt).split()))
